import { pgEnum, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Primary key: random UUID v4 generated by Postgres. */
export const id = () => uuid().primaryKey().defaultRandom();

/** Business calendar dates are stored as `date` and handled as `YYYY-MM-DD` strings. */
export const tz = () => timestamp({ withTimezone: true, mode: 'date' });

export const timestamps = {
  createdAt: tz().notNull().defaultNow(),
  updatedAt: tz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

export const userRole = pgEnum('user_role', ['admin', 'coach']);
export const userStatus = pgEnum('user_status', ['invited', 'active', 'disabled']);
export const authTokenType = pgEnum('auth_token_type', ['invite', 'password_reset']);

export const studentStatus = pgEnum('student_status', ['active', 'left']);
export const gender = pgEnum('gender', ['male', 'female', 'other']);

export const attendanceStatus = pgEnum('attendance_status', [
  'present',
  'absent',
  'late',
  'excused',
]);

export const feedbackStatus = pgEnum('feedback_status', ['draft', 'submitted']);

export const invoiceStatus = pgEnum('invoice_status', ['due', 'paid', 'refunded', 'cancelled']);
export const paymentMode = pgEnum('payment_mode', [
  'cash',
  'upi',
  'bank_transfer',
  'card',
  'cheque',
  'other',
]);
export const paymentStatus = pgEnum('payment_status', ['completed', 'reverted', 'refunded']);

export const jobRunStatus = pgEnum('job_run_status', ['running', 'succeeded', 'failed']);
